import Foundation
import SwiftData

/// A single income or expense, stored in the currency it actually happened in.
@Model
final class Entry {
    var id: UUID = UUID()
    var title: String = ""
    var amount: Decimal = 0
    var currencyCode: String = "USD"
    var date: Date = Date()
    var categoryRaw: String = EntryCategory.otherExpense.rawValue
    var paymentMethodRaw: String = PaymentMethod.debitCard.rawValue
    var note: String = ""
    /// Set when the entry was generated by a `RecurringPayment`.
    var recurringID: UUID?
    var createdAt: Date = Date()

    init(
        title: String = "",
        amount: Decimal,
        currencyCode: String,
        date: Date = .now,
        category: EntryCategory,
        paymentMethod: PaymentMethod = .debitCard,
        note: String = "",
        recurringID: UUID? = nil
    ) {
        self.title = title
        self.amount = amount
        self.currencyCode = currencyCode
        self.date = date
        self.categoryRaw = category.rawValue
        self.paymentMethodRaw = paymentMethod.rawValue
        self.note = note
        self.recurringID = recurringID
    }

    var category: EntryCategory {
        get { EntryCategory(rawValue: categoryRaw) ?? .otherExpense }
        set { categoryRaw = newValue.rawValue }
    }

    var paymentMethod: PaymentMethod {
        get { PaymentMethod(rawValue: paymentMethodRaw) ?? .other }
        set { paymentMethodRaw = newValue.rawValue }
    }

    var kind: EntryKind { category.kind }

    var displayTitle: String { title.isEmpty ? category.title : title }

    var snapshot: EntrySnapshot {
        EntrySnapshot(amount: amount, currencyCode: currencyCode, date: date, category: category, paymentMethod: paymentMethod)
    }
}

/// Plain value copy of an entry used by the report and insight engines (easy to unit test).
struct EntrySnapshot: Hashable {
    var amount: Decimal
    var currencyCode: String
    var date: Date
    var category: EntryCategory
    var paymentMethod: PaymentMethod = .debitCard

    var kind: EntryKind { category.kind }
}
